package com.djibtout.backend.entity;
import jakarta.persistence.*;import java.util.*;
@Entity @Table(name="category_attributes") public class CategoryAttribute{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private Category category;@Column(nullable=false,length=80)private String name;private boolean required;@ElementCollection @CollectionTable(name="category_attribute_values",joinColumns=@JoinColumn(name="attribute_id"))@Column(name="value",length=100)private List<String> values=new ArrayList<>();public Long getId(){return id;}public Category getCategory(){return category;}public void setCategory(Category v){category=v;}public String getName(){return name;}public void setName(String v){name=v;}public boolean isRequired(){return required;}public void setRequired(boolean v){required=v;}public List<String> getValues(){return values;}public void setValues(List<String> v){values=v==null?new ArrayList<>():v;}}
